import os
import re

DEFAULTS = {
    "PAYHOOK_API_TOKEN": None,
    "PAYHOOK_WEBHOOK_SECRET": None,
    "PAYHOOK_ENDPOINT": "https://api.payments.example/v1",
    "PAYHOOK_TIMEOUT": "10",
    "PAYHOOK_REGION": "eu",
}

# Values of these keys are never printed in full (see render_doctor).
SECRET_KEYS = {"PAYHOOK_API_TOKEN", "PAYHOOK_WEBHOOK_SECRET"}

# Internal source names -> the wording shown to people.
SOURCE_LABELS = {
    "env": "environment",
    ".env": ".env",
    "default": "default",
}

_EXPORT_PREFIX = re.compile(r"^export\s+")


def _parse_dotenv_value(raw):
    raw = raw.strip()
    if raw[:1] in ("'", '"'):
        end = raw.find(raw[0], 1)
        if end != -1:
            # Everything after the closing quote (e.g. a comment) is ignored.
            return raw[1:end]
        # Unterminated quote: keep the text as written rather than guess.
        return raw
    # Unquoted: a " #" starts an inline comment.
    match = re.search(r"\s#", raw)
    if match:
        return raw[: match.start()].rstrip()
    return raw


def read_dotenv(path):
    values = {}
    if not os.path.exists(path):
        return values
    with open(path, encoding="utf-8") as handle:
        for line in handle:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            line = _EXPORT_PREFIX.sub("", line)
            if "=" not in line:
                continue
            key, _, value = line.partition("=")
            key = key.strip()
            if not key:
                continue
            values[key] = _parse_dotenv_value(value)
    return values


def load_config(environ=None, dotenv_path=".env"):
    environ = os.environ if environ is None else environ
    dotenv = read_dotenv(dotenv_path)
    config = {}
    for key, default in DEFAULTS.items():
        if key in environ:
            config[key] = (environ[key], "env")
        elif key in dotenv:
            config[key] = (dotenv[key], ".env")
        else:
            config[key] = (default, "default")
    return config


def _display_value(key, value):
    if value is None:
        return "(not set)"
    if key in SECRET_KEYS:
        # Show only the type prefix (e.g. "sk_", "whsec_") and the length.
        prefix = value[: value.index("_") + 1] if "_" in value else ""
        return f"{prefix}… (redacted, {len(value)} chars)"
    return value


def render_doctor(config, dotenv_path=".env"):
    abs_path = os.path.abspath(dotenv_path)
    found = "found" if os.path.exists(abs_path) else "not found"
    lines = [
        "payhook doctor",
        f"dotenv file: {abs_path} ({found})",
        "",
    ]
    width = max(len(key) for key in config)
    for key, (value, source) in config.items():
        lines.append(
            f"{key:<{width}}  {_display_value(key, value)}  [{SOURCE_LABELS[source]}]"
        )
    lines.append("")
    lines.append("Secrets are redacted. Sources: environment > .env > default.")
    return "\n".join(lines)

